@IsTest private class MemberDeleteProbe {
 @IsTest static void observe() {
  Group team = new Group(Name='Owned delete team', DeveloperName='OwnedDeleteTeam', Type='Regular');
  insert team;
  GroupMember membership = new GroupMember(GroupId=team.Id, UserOrGroupId=UserInfo.getUserId());
  insert membership;
  Integer inserted = [SELECT COUNT() FROM GroupMember WHERE GroupId=:team.Id];
  delete membership;
  Integer remaining = [SELECT COUNT() FROM GroupMember WHERE GroupId=:team.Id];
  String mixed = 'none';
  try { insert new Account(Name='Owned mixed control'); }
  catch (DmlException e) { mixed = String.valueOf(e.getDmlType(0)); }
  System.assert(false, 'P|MD01T|inserted:'+inserted+'|remaining:'+remaining+'|mixed:'+mixed);
 }
}
